    "cointegrated_pairs = stat_sig[(stat_sig['ADF_Statistic'] < 0.05) & (stat_sig['EG_Test'] < 0.05) & (stat_sig['Johansen_Test_trace'] > stat_sig['Johansen_Test_cvt'])].index.tolist()\n",
